tar -xzf "$PAY/p.tgz" -C "$PAY"; rm -f "$PAY/p.tgz"
test "$(md5sum < "$PAY/payload_146.json" | cut -c1-32)" = f925d8c9507f40752664bf5995d2269b || { echo "$T: embedded payload damaged" >&2; exit 1; }
test "$(md5sum < "$PAY/apply.py" | cut -c1-32)" = cc0e5303eecf4fd19c339bff697c6fe2 || { echo "$T: embedded apply.py damaged" >&2; exit 1; }
test "$(md5sum < "$PAY/meeting_pages.py" | cut -c1-32)" = 6a115e8dce53e6b83bd9db5a477f1f55 || { echo "$T: embedded meeting_pages.py damaged" >&2; exit 1; }
python3 "$PAY/apply.py" "$M" "$PAY/payload_146.json"
# meeting pages: the shared build tool when present, else the embedded copy (same file on 22 Nov)
MP="$BUILD/meeting_pages.py"; test -s "$MP" || MP="$PAY/meeting_pages.py"
python3 "$MP" "$M" >/dev/null
python3 - "$M" <<'PY'
import json, os, sys
M = sys.argv[1]; dec = json.JSONDecoder()
def val(p, c):
    for l in open(p, encoding="utf-8").read().split("\n"):
        if l.startswith(c): return dec.raw_decode(l[len(c):])[0]
    raise SystemExit("146: " + c + " missing in " + p)
def refs(e): return [d["url"].rsplit("ref=", 1)[-1] for d in e.get("docs", [])]
subs = {s["key"]: {m["n"]: m for m in s["meetings"]} for s in val(f"{M}/index.html", "const SUBS=")}
pages = {"main": ("index.html", "meetings.json"), "smegov": ("sub-smegov.html", "sub-smegov.json"),
         "smeurgent": ("sub-smeurgent.html", "sub-smeurgent.json"), "industry": ("sub-industry.html", "sub-industry.json")}
for key, (h, j) in pages.items():
    srcs = [{m["n"]: m for m in val(f"{M}/{h}", "const DATA=")}, {m["n"]: m for m in json.load(open(f"{M}/{j}", encoding="utf-8"))}]
    for s in srcs:
        if key == "main":
            assert "11216651" in refs(s[33]) and "11147054" not in refs(s[33]) and refs(s[33]).count("11204694") == 1, "146: main 33 docs"
            assert "11216297" in refs(s[34]) and "11204700" in refs(s[34]) and "11195070" not in refs(s[34]) and not s[34].get("upcoming"), "146: main 34"
            assert s[35].get("upcoming") and s[35]["time"] == "14.00" and "11216585" in refs(s[35]), "146: main 35"
        if key == "smegov":
            assert "11225596" in refs(s[15]) and "11216282" in refs(s[17]) and "11225978" in refs(s[18]) and s[18].get("upcoming"), "146: smegov"
            assert s[16].get("summary"), "146: smegov 16 kept"
        if key == "smeurgent": assert s[18].get("upcoming") and not s[17].get("upcoming"), "146: smeurgent"
        if key == "industry": assert s[19].get("upcoming") and not s[18].get("upcoming"), "146: industry"
# home-page SUBS rows hold only date + docs
g, u, i = subs["smegov"], subs["smeurgent"], subs["industry"]
assert "11225596" in refs(g[15]) and "11216282" in refs(g[17]) and "11225978" in refs(g[18]) and 18 in u and 19 in i, "146: SUBS"
for f in ("m/35.html", "m/smegov-18.html", "m/smeurgent-18.html", "m/industry-19.html", "cal/35.ics", "s/35.html", "s/smegov-18.html"):
    assert os.path.getsize(f"{M}/{f}") > 200, "146: " + f
m33 = open(f"{M}/m/33.html", encoding="utf-8").read(); m34 = open(f"{M}/m/34.html", encoding="utf-8").read()
assert "ref=11147054" not in m33 and "ref=11195070" not in m34 and "ref=11204694" in m33, "146: meeting pages"
print("146_commerce_1122_updates OK")
PY
